"use client";

import { useEffect, useRef, useState } from "react";
import gsap from "gsap";
import Magnetic from "@/components/animations/Magnetic";

interface HeaderProps {
  activeView?: "main" | "about" | "work";
  onViewChange?: (view: "main" | "about" | "work") => void;
}

function HeaderNavItem({
  id,
  label,
  isActive,
  onClick,
}: {
  id: string;
  label: string;
  isActive: boolean;
  onClick: () => void;
}) {
  const activeLineRef = useRef<HTMLDivElement>(null);
  const hoverLineRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const isMountedRef = useRef(false);

  useEffect(() => {
    return () => {
      if (activeLineRef.current) gsap.killTweensOf(activeLineRef.current);
      if (hoverLineRef.current) gsap.killTweensOf(hoverLineRef.current);
      if (textRef.current) gsap.killTweensOf(textRef.current);
    };
  }, []);

  useEffect(() => {
    if (!activeLineRef.current) return;

    if (!isMountedRef.current) {
      isMountedRef.current = true;
      gsap.set(activeLineRef.current, {
        scaleX: isActive ? 1 : 0,
        transformOrigin: "left",
      });
      if (hoverLineRef.current) {
        gsap.set(hoverLineRef.current, { scaleX: 0, transformOrigin: "left" });
      }
      return;
    }

    gsap.killTweensOf(activeLineRef.current);
    if (isActive) {
      if (hoverLineRef.current) {
        gsap.killTweensOf(hoverLineRef.current);
        gsap.set(hoverLineRef.current, { scaleX: 0 });
      }
      gsap.fromTo(
        activeLineRef.current,
        { scaleX: 0, transformOrigin: "left" },
        { scaleX: 1, duration: 0.42, ease: "power3.out" }
      );
    } else {
      gsap.to(activeLineRef.current, {
        scaleX: 0,
        transformOrigin: "right",
        duration: 0.32,
        ease: "power2.inOut",
      });
    }
  }, [isActive]);

  const handleMouseEnter = () => {
    if (isActive) return;
    if (hoverLineRef.current) {
      gsap.killTweensOf(hoverLineRef.current);
      gsap.fromTo(
        hoverLineRef.current,
        { scaleX: 0, transformOrigin: "left" },
        { scaleX: 1, duration: 0.32, ease: "power2.out" }
      );
    }
    if (textRef.current) {
      gsap.killTweensOf(textRef.current);
      gsap.to(textRef.current, {
        y: -1.5,
        duration: 0.22,
        ease: "power2.out",
      });
    }
  };

  const handleMouseLeave = () => {
    if (isActive) return;
    if (hoverLineRef.current) {
      gsap.killTweensOf(hoverLineRef.current);
      gsap.to(hoverLineRef.current, {
        scaleX: 0,
        transformOrigin: "right",
        duration: 0.28,
        ease: "power2.inOut",
      });
    }
    if (textRef.current) {
      gsap.killTweensOf(textRef.current);
      gsap.to(textRef.current, {
        y: 0,
        duration: 0.22,
        ease: "power2.out",
      });
    }
  };

  return (
    <button
      id={id}
      type="button"
      onClick={onClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      className="group relative flex flex-col items-center py-1 px-1 cursor-pointer select-none"
    >
      <span
        ref={textRef}
        className={`font-mono text-xs sm:text-sm tracking-widest uppercase transition-colors duration-200 will-change-transform ${isActive
          ? "text-neutral-950 font-bold"
          : "text-neutral-500 group-hover:text-neutral-950 font-medium"
          }`}
      >
        {label}
      </span>
      <div className="relative w-full h-[2.5px] sm:h-[3px] mt-1 overflow-hidden rounded-[1px]">
        <div className="absolute inset-0 bg-neutral-900/20" />
        <div
          ref={hoverLineRef}
          className="absolute inset-0 bg-neutral-900/85 origin-left will-change-transform pointer-events-none"
        />
        <div
          ref={activeLineRef}
          className="absolute inset-0 bg-neutral-950 origin-left will-change-transform pointer-events-none"
        />
      </div>
    </button>
  );
}

const GLITCH_GLYPHS = "!<>-_\\/[]{}—=+*^?#_01";

function HeaderLogo() {
  const [isAlt, setIsAlt] = useState(false);
  const [text, setText] = useState<{ prefix: string; suffix: string }>({
    prefix: "markappscript",
    suffix: ".dev",
  });
  const [isGlitching, setIsGlitching] = useState(false);
  const animFrameRef = useRef<number | null>(null);
  const btnRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
  }, []);

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isGlitching) return;
    setIsGlitching(true);

    const nextIsAlt = !isAlt;
    setIsAlt(nextIsAlt);

    const targetPrefix = nextIsAlt ? "Code by Mark" : "markappscript";
    const targetSuffix = nextIsAlt ? "©" : ".dev";
    const fullTarget = targetPrefix + targetSuffix;

    if (btnRef.current) {
      gsap.killTweensOf(btnRef.current);
      gsap.timeline()
        .to(btnRef.current, { x: -2, y: 1, duration: 0.04, ease: "none" })
        .to(btnRef.current, { x: 2.5, y: -1, duration: 0.04, ease: "none" })
        .to(btnRef.current, { x: -1.5, y: 0.5, duration: 0.04, ease: "none" })
        .to(btnRef.current, { x: 1, y: -0.5, duration: 0.04, ease: "none" })
        .to(btnRef.current, { x: 0, y: 0, duration: 0.04, ease: "none" });
    }

    let frame = 0;
    const totalFrames = 12;

    const animate = () => {
      frame++;
      const progress = frame / totalFrames;

      if (frame >= totalFrames) {
        setText({ prefix: targetPrefix, suffix: targetSuffix });
        setIsGlitching(false);
        return;
      }

      let scrambled = "";
      for (let i = 0; i < fullTarget.length; i++) {
        if (progress > i / fullTarget.length + 0.18) {
          scrambled += fullTarget[i];
        } else {
          scrambled += GLITCH_GLYPHS[Math.floor(Math.random() * GLITCH_GLYPHS.length)];
        }
      }

      const splitIndex = targetPrefix.length;
      setText({
        prefix: scrambled.slice(0, splitIndex),
        suffix: scrambled.slice(splitIndex),
      });

      animFrameRef.current = requestAnimationFrame(animate);
    };

    animFrameRef.current = requestAnimationFrame(animate);
  };

  return (
    <Magnetic strength={0.2}>
      <button
        ref={btnRef}
        type="button"
        onClick={handleClick}
        className="flex items-baseline select-none cursor-pointer text-left will-change-transform"
        aria-label="Toggle logo title"
      >
        <span
          className={`font-bold tracking-tight text-xs sm:text-base text-black transition-all ${isGlitching ? "drop-shadow-[1.5px_0_0_rgba(147,51,234,0.8)]" : ""
            }`}
        >
          {text.prefix}
        </span>
        <span
          className={`font-bold tracking-tight text-xs sm:text-base transition-all ${isAlt ? "text-black" : "text-purple-600"
            } ${isGlitching ? "drop-shadow-[-1.5px_0_0_rgba(6,182,212,0.8)]" : ""}`}
        >
          {text.suffix}
        </span>
      </button>
    </Magnetic>
  );
}

export default function Header({ activeView = "main", onViewChange }: HeaderProps) {
  const headerRef = useRef<HTMLElement>(null);
  const prevViewRef = useRef(activeView);

  useEffect(() => {
    if (!headerRef.current) return;
    const isWhite = activeView === "work" || activeView === "about";
    const wasAbout = prevViewRef.current === "about";
    const isReturningFromAbout = wasAbout && activeView === "main";

    gsap.killTweensOf(headerRef.current);

    const duration = isReturningFromAbout ? 0.09 : 0.65;
    const ease = isReturningFromAbout ? "power2.out" : "power3.out";

    gsap.to(headerRef.current, {
      backgroundColor: isWhite ? "#ffffff" : "rgba(255, 255, 255, 0)",
      duration,
      ease,
    });

    prevViewRef.current = activeView;
  }, [activeView]);

  const handleMainClick = () => {
    if (activeView !== "about") return;
    onViewChange?.("main");
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent("portfolio-trigger-main"));
    }
  };

  const handleAboutClick = () => {
    if (activeView === "about") return;
    onViewChange?.("about");
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent("portfolio-view-about"));
    }
  };

  return (
    <header
      id="header-nav"
      ref={headerRef}
      className="fixed top-0 left-0 right-0 z-50 w-full h-16 sm:h-20 bg-transparent px-4 sm:px-12 flex items-center justify-between pointer-events-none opacity-0"
    >
      <div className="pointer-events-auto">
        <HeaderLogo />
      </div>

      <div className="pointer-events-auto absolute left-1/2 -translate-x-1/2 flex items-center gap-6 sm:gap-10 select-none">
        <HeaderNavItem
          id="nav-btn-main"
          label="MAIN"
          isActive={activeView === "main"}
          onClick={handleMainClick}
        />
        <HeaderNavItem
          id="nav-btn-about"
          label="ABOUT"
          isActive={activeView === "about"}
          onClick={handleAboutClick}
        />
      </div>

      <div className="pointer-events-auto flex items-center gap-3 sm:gap-5 text-sm text-neutral-800">
        <Magnetic strength={0.15}>
          <a
            href="mailto:markappscript@gmail.com"
            className="hidden sm:inline-block font-mono text-xs sm:text-sm font-semibold text-neutral-700 hover:text-black tracking-tight transition-colors"
          >
            markappscript@gmail.com
          </a>
        </Magnetic>

        <div className="flex items-center gap-1.5 sm:gap-2">
          <Magnetic strength={0.2}>
            <a
              href="https://www.linkedin.com/in/mark-bryan-poticar-7954041b4"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="LinkedIn Profile"
              className="w-8 h-8 rounded-full flex items-center justify-center text-neutral-700 hover:text-[#0a66c2] hover:bg-neutral-900/5 transition-all"
            >
              <svg className="w-4 h-4 fill-current" viewBox="0 0 24 24">
                <path d="M19 3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h14m-.5 15.5v-5.3a3.26 3.26 0 0 0-3.26-3.26c-.85 0-1.84.52-2.28 1.3v-1.11h-2.79v8.37h2.79v-4.93c0-.77.62-1.4 1.39-1.4a1.4 1.4 0 0 1 1.4 1.4v4.93h2.75M6.88 8.56a1.68 1.68 0 0 0 1.68-1.68c0-.93-.75-1.69-1.68-1.69a1.69 1.69 0 0 0-1.69 1.69c0 .93.76 1.68 1.69 1.68m1.39 9.94v-8.37H5.5v8.37h2.77z" />
              </svg>
            </a>
          </Magnetic>

          <Magnetic strength={0.2}>
            <a
              href="https://v2.onlinejobs.ph/jobseekers/info/4228954"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="OnlineJobs.ph Profile"
              className="w-8 h-8 rounded-full flex items-center justify-center text-neutral-700 hover:bg-neutral-900/5 transition-all group"
            >
              <img
                src="/images/onlinejobs-icon.png"
                alt="OnlineJobs.ph"
                className="w-4 h-4 sm:w-[18px] sm:h-[18px] object-contain opacity-75 group-hover:opacity-100 group-hover:scale-110 transition-all"
              />
            </a>
          </Magnetic>
        </div>
      </div>
    </header>
  );
}
